class Hund {
private:
    std::string name;      // privat: nur Methoden
public:
    Hund(std::string n) {  // Konstruktor (wie die Klasse)
        name = n;
    }
    void bellen() const {
        std::cout << name << " sagt Wuff!";
    }
};

Hund h("Rex");   // Objekt erzeugen
h.bellen();       // Rex sagt Wuff!
