class Konto {
private:
    int stand;
public:
    Konto(int start) : stand(start) {}

    void einzahlen(int betrag) {
        if (betrag > 0) stand += betrag;
    }

    int getStand() const {   // const: ändert nichts
        return stand;
    }
};

Konto k(100);
k.einzahlen(50);
std::cout << k.getStand();   // 150

class Tier {
public:
    Tier(std::string n) : name(n) {}
    virtual std::string gib_laut() { return "..."; }
protected:
    std::string name;
};

class Hund : public Tier {
public:
    Hund(std::string n) : Tier(n) {}
    std::string gib_laut() override { return "Wuff"; }
};

Hund h("Rex");
std::cout << h.gib_laut();   // Wuff
